      "id": 2,
      "claim": "A laptop is classified as a consumer electronic device.",
      "evidence": "Industry classification systems (e.g., NAICS code 334111 – Electronic Computer Manufacturing) place laptops under “electronic computers and peripherals,” confirming they are electronics.",
      "weight": 0.25,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "No laptop model or manufacturer is listed as holding a Fairtrade International certification.",
      "evidence": "A search of Fairtrade International’s certified‑product database (accessed July 2024) returns zero results for any laptop brand or model, and sustainability reports of major laptop makers (Dell, HP, Lenovo, Apple, ASUS, Acer, Framework) contain no mention of Fairtrade certification.",
      "weight": 0.20,
      "depends_on": [2]
    },
